---分享按钮点击回调
function PreDownloadCatCollectionDialog:BtnShareOnClickHandler()
    if GameUtils.IsWindow() then
        GameUtils.Toast(localize('请移动至手机端进行分享'))
        return
    end

    ---@type PreDownloadCatPoolVo
    local catPoolData            = CfUtils.GetCfVo(AutoIds.IdSetting3105, "PreDownloadCatPoolVo", self._selectedIndex)
    local catShareTimelineIndex  = math.random(#PreDownloadConstants.CatShareTimelineDefines)
    local catShareTimelineDefine = PreDownloadConstants.CatShareTimelineDefines[catShareTimelineIndex]
    local catGeneNameId          = tostring(catPoolData.geneId)
    UIModule.OpenDialog({id = Constants.UITypeIds.CommonSharePreviewDialog, parameters = {
        shareType = Constants.ShareType.PRE_DOWNLOAD_CALL,
        videoArgs = {
            videoNameId  = string.format('PreDownload_CallCat_%s_%d', catGeneNameId, catShareTimelineIndex),
            timelinePath = catShareTimelineDefine.PREFAB,
            tlCameraName = catShareTimelineDefine.CAMERA,
            ---@param timelineIns UnityEngine.GameObject
            ---@param tlDirector UnityEngine.Playables.PlayableDirector
            tlInitCallback = function(timelineIns, tlDirector)
                -- disable sample cat
                local catSampleName = catShareTimelineDefine.CAT_SAMPLE
                local catSampleGo   = timelineIns.transform:Find(catSampleName)
                CfUtils.SetActive(catSampleGo, false)

                -- load gene cat
                local timelineCatGo = nil
                cs_coroutine.yield_return(PreDownloadUtils.LoadGeneCat(catPoolData.geneId, timelineIns, function(catGo, catId)
                    timelineCatGo = catGo
                    local catAnimancerComp = timelineCatGo:GetComponent(typeof(NamedAnimancerComponent))
                    if not isNull(catAnimancerComp) then
                        catAnimancerComp.enabled = false
                    end
                end))
                timelineCatGo.transform:SetParent(timelineIns.transform, false)

                -- bind gene cat
                local catTrackName = catShareTimelineDefine.CAT_TRACK
                GachaponUtils.BindTimeline(tlDirector, catTrackName, timelineCatGo)
            end
        },
    }})
end

---猫球列表处理
function PreDownloadCatCollectionDialog:OnGetItemByIndex(gridView, index)
    if index < 0 then return nil end
    
    local cell = gridView:NewListViewItem(CatListCellName)
    
    local scr = CfUtils.GetLuaScr(cell, CatListCellPath)
    if scr then
        local isSelected = index + 1 == self._selectedIndex
        local catPoolData = CfUtils.GetCfVo(AutoIds.IdSetting3105, "PreDownloadCatPoolVo", index+1)
        local isUnlock = self._genesDict[tostring(catPoolData.geneId)] or false
        scr:RefreshSelf(index + 1, isSelected, isUnlock, Bind(self, self.CellOnClickHandler))
    end
    return cell
end

---cell点击回调
---@param index integer cell序号
function PreDownloadCatCollectionDialog:CellOnClickHandler(index)
    -- 判断是否解锁
    ---@type PreDownloadCatPoolVo
    local catPoolData = CfUtils.GetCfVo(AutoIds.IdSetting3105, "PreDownloadCatPoolVo", index)
    if not self._genesDict[tostring(catPoolData.geneId)] then
        return
    end

    if self._selectedIndex == index then
        return
    end
    
    -- 刷新cell状态
    if self._selectedIndex then
        self:RefreshCatListCellSelectedState(self._selectedIndex, false)
    end

    self:RefreshCatListCellSelectedState(index, true)
    
    self._selectedIndex = index
    self:StopCatCo()
    self:RefreshCatPanel()
end
