---刷新猫球列表
function PreDownloadCatCollectionDialog:RefreshCatGridView()
    local catNum = CfUtils.GetCf(AutoIds.IdSetting3105, "PreDownloadCatPoolVo"):Count()
    GameUtils.ReloadData(self.ScrollView, catNum)
end

---刷新猫球层
function PreDownloadCatCollectionDialog:RefreshCatPanel()
    if self._selectedIndex then
        KTool.SetActive(self.CatContent, true)
        KTool.SetActive(self.CatEmpty, false)
        self:RefreshCatUI()
    else
        KTool.SetActive(self.CatContent, false)
        KTool.SetActive(self.CatEmpty, true)
    end
end

---刷新猫球UI
function PreDownloadCatCollectionDialog:RefreshCatUI()
    ---@type PreDownloadCatPoolVo
    local catPoolData = CfUtils.GetCfVo(AutoIds.IdSetting3105, "PreDownloadCatPoolVo", self._selectedIndex)
    ---@type CatHouseCatDataVo
    local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", catPoolData.geneId)

    CfUtils.FillText(self.TextCatName, catHouseCatDataVo.name)
    CfUtils.FillImage(self.ImgIcon, catHouseCatDataVo.icon)
    
    KTool.SetActive(self.ButtonShare, PreDownloadUtils.IsShowShareButton())
    
    self:RefreshCatModel(catPoolData.geneId)
end

---刷新猫球模型
---param geneId integer 基因id   
function PreDownloadCatCollectionDialog:RefreshCatModel(geneId)
    self._catCameraGo, self._catCo = PreDownloadUtils.InitCat(geneId)
    local captureCamera = self._catCameraGo.gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
    self.CatNode.texture = captureCamera.targetTexture
end

---刷新列表cell选中状态
---@param index      integer cell序号
---@param isSelected boolean 是否选中
function PreDownloadCatCollectionDialog:RefreshCatListCellSelectedState(index, isSelected)
    local go = self.ScrollView:GetShownItemByItemIndex(index - 1)
    if not isNull(go) then
        local scr = CfUtils.GetLuaScr(go, CatListCellPath)
        scr:RefreshSelectState(isSelected)
    end
end

---关闭猫球初始化co
function PreDownloadCatCollectionDialog:StopCatCo()
    if not isNull(self._catCo) then
        cs_coroutine.stop(self._catCo)
        self._catCo = nil
    end
end

---销毁相机节点
function PreDownloadCatCollectionDialog:DestroyCatCameraGo()
    if not isNull(self._catCameraGo) then
        KTool.SafeDelete(self._catCameraGo)
    end
end

---控制场景灯光
---@param isEnabled boolean 是否启用
function PreDownloadCatCollectionDialog:SetSceneLightEnabled(isEnabled)
    ---@type SceneInstance
    local sceneIns = SceneManagement:GetInstance():GetSceneInstance(Constants.IdSceneSetting21)
    if not isNull(sceneIns) then
        ---@type UnityEngine.GameObject
        local lightGo = sceneIns:GetCacheObjectByName("Directional Light")
        ---@type UnityEngine.Light
        local lightCom = lightGo:GetComponent(typeof(Light))
        lightCom.enabled = checkBool(isEnabled)
    end
end

---开关猫球相机
---@param state boolean 是否启用
function PreDownloadCatCollectionDialog:SetCatCameraEnable(state)
    if isNull(self._catCameraGo) then return end
    local camComp = self._catCameraGo.gameObject:GetComponentInChildren(typeof(Camera))
    camComp.enabled = checkBool(state)
end
